import{c as a,Q as d,j as e,m as l}from"./chunks/framework.DOi4mjdC.js";const A=JSON.parse('{"title":"SetCtrlSpr(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetCtrlSpr\\\\(ISASI\\\\)","slug":"setctrlsprisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/系统变量访问/SetCtrlSpr(ISASI).md","filePath":"api/SIMD-API/基础API/系统变量访问/SetCtrlSpr(ISASI).md"}'),s={name:"api/SIMD-API/基础API/系统变量访问/SetCtrlSpr(ISASI).md"};function r(i,t,n,h,o,b){return d(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="setctrlspr-isasi" tabindex="-1">SetCtrlSpr(ISASI) <a class="header-anchor" href="#setctrlspr-isasi" aria-label="Permalink to &quot;SetCtrlSpr\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>对CTRL寄存器（控制寄存器）的特定比特位进行设置。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;int8_t startBit, int8_t endBit&gt;</span></span>
<span class="line"><span>__aicore__ static inline void SetCtrlSpr(int64_t value)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>startBit</td><td>起始比特位索引。</td></tr><tr><td>endBit</td><td>终止比特位索引。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>value</td><td>输入</td><td>起止比特位上新设置的值。</td></tr></tbody></table><p><strong>表 3</strong> Ascend 950PR/Ascend 950DT常用CTRL寄存器比特位说明</p><table tabindex="0"><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[8:6]</td><td>用于控制数据从L0C Buffer/Unified Buffer/L1 Buffer搬运至Global Memory时原子操作的使能及数据类型选择。 3&#39;b000：不使能原子操作；3&#39;b001：使能原子操作，数据类型为float；3&#39;b010：使能原子操作，数据类型为half；3&#39;b011：使能原子操作，数据类型为int16_t；3&#39;b100：使能原子操作，数据类型为int32_t；3&#39;b101：使能原子操作，数据类型为int8_t；3&#39;b110：使能原子操作，数据类型为bfloat16_t。</td><td>3&#39;b000</td><td>不涉及</td></tr><tr><td>CTRL[10:9]</td><td>用于控制原子操作的类型，仅在CTRL[8:6]使能原子操作时生效。 2&#39;b00：选择ADD操作；2&#39;b01：选择MAX操作；2&#39;b10：选择MIN操作。</td><td>2&#39;b00</td><td>不涉及</td></tr><tr><td>CTRL[45]</td><td>用于控制左右矩阵数据做Mmad计算时的处理方式。 1&#39;b0：按照原数据类型进行处理；1&#39;b1：左右矩阵数据均为fp8_e4m3fn_t时，数据视为hifloat8_t进行矩阵乘法计算。其他场景按照原数据类型进行处理。</td><td>1&#39;b0</td><td>不涉及</td></tr><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式，仅在CTRL[60]使能时生效。 1&#39;b0：饱和模式，INF输出会被饱和为±MAX， NaN输出会被饱和为0；1&#39;b1：非饱和模式，INF/NAN保持原输出。 该控制位仅支持如下数据类型： 浮点数计算时支持half数据类型；浮点数精度转换时支持如下数据类型：hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t。</td><td>1&#39;b0</td><td>配合使用的API： 矢量计算API原子操作API精度转换指令 使用约束： 需要满足数据类型限制。执行原子操作过程中，如果需要重新配置该控制位，需要调用DataCacheCleanAndInvalid先清除当前Cache Line状态并将当前数据写出，防止饱和模式变更影响当前数据。具体调用示例可参考原子操作中，half类型配置全局非饱和模式示例。</td></tr><tr><td>CTRL[50]</td><td>用于控制浮点数精度转换时的NAN饱和模式，在CTRL[48]设置为饱和模式时生效。 1&#39;b0：NAN输出会被转换为0.0； 1&#39;b1：NAN输出会保持NAN。 该控制位仅支持如下数据类型： fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t。</td><td>1&#39;b0</td><td>精度转换指令（需要满足数据类型限制）。</td></tr><tr><td>CTRL[53]</td><td>用于控制整数计算指令的饱和模式。 1&#39;b0：截断模式，溢出值按目标数据类型位数截断，保留低位，舍弃高位； 1&#39;b1：饱和模式，溢出值饱和到±MAX。</td><td>1&#39;b0</td><td>矢量计算API（输入输出数据类型为整数）。</td></tr><tr><td>CTRL[59]</td><td>用于控制浮点数转整数或整数转整数时的精度转换饱和模式，仅在CTRL[60]使能时生效。 1&#39;b0：饱和模式：溢出值饱和到±MAX； 1&#39;b1：截断模式：溢出值按目标数据类型位数截断，保留低位，舍弃高位。</td><td>1&#39;b0</td><td>精度转换指令。</td></tr><tr><td>CTRL[60]</td><td>用于控制饱和模式的全局生效方式。 1&#39;b0：单指令设置饱和； 1&#39;b1：全局设置饱和。</td><td>1&#39;b1</td><td>该控制位可与Reg矢量计算API Cast配合使用，或与CTRL[48]、CTRL[59]配合使用，具体配置信息参考表6。</td></tr></tbody></table><p><strong>表 4</strong> Atlas A2 训练系列产品/Atlas A2 推理系列产品常用CTRL寄存器比特位说明</p><table tabindex="0"><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式。 1&#39;b0：饱和模式，INF输出会被饱和为±MAX， NaN输出会被饱和为0；1&#39;b1：非饱和模式，INF/NAN保持原输出。 该控制位仅支持如下数据类型： 浮点数计算时支持half、bfloat16_t数据类型；浮点数精度转换时支持如下数据类型：half、bfloat16_t。</td><td>1&#39;b0</td><td>不涉及</td></tr></tbody></table><p><strong>表 5</strong> Atlas A3 训练系列产品/Atlas A3 推理系列产品常用CTRL寄存器比特位说明</p><table tabindex="0"><thead><tr><th>CTRL寄存器比特位</th><th>功能</th><th>默认值</th><th>配合使用的API</th></tr></thead><tbody><tr><td>CTRL[48]</td><td>用于控制浮点数计算和浮点数精度转换时的饱和模式。 1&#39;b0：饱和模式，INF输出会被饱和为±MAX， NaN输出会被饱和为0；1&#39;b1：非饱和模式，INF/NAN保持原输出。 该控制位仅支持如下数据类型： 浮点数计算时支持half、bfloat16_t数据类型；浮点数精度转换时支持如下数据类型：half、bfloat16_t。</td><td>1&#39;b0</td><td>不涉及</td></tr></tbody></table><p><strong>表 6</strong> Ascend 950PR/Ascend 950DT饱和模式全局或单指令生效配置表</p><table tabindex="0"><thead><tr><th>全局使能位</th><th>控制位</th><th>功能描述</th></tr></thead><tbody><tr><td>CTRL[60] = 1&#39;b0</td><td>Reg矢量计算Cast API的trait模板参数中satMode设置为SatMode::NO_SAT。</td><td>单指令非饱和模式。</td></tr><tr><td>CTRL[60] = 1&#39;b0</td><td>Reg矢量计算Cast API的trait模板参数中satMode设置为 SatMode::SAT。</td><td>单指令饱和模式。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[48] = 1&#39;b1</td><td>全局非饱和模式（浮点数计算和浮点数精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[48] = 1&#39;b0</td><td>全局饱和模式（浮点数计算和浮点数精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[59] = 1&#39;b1</td><td>全局非饱和模式（浮点数转整数或整数转整数时的精度转换）。</td></tr><tr><td>CTRL[60] = 1&#39;b1</td><td>CTRL[59] = 1&#39;b0</td><td>全局饱和模式（浮点数转整数或整数转整数时的精度转换）。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>Ascend 950PR/Ascend 950DT仅支持CTRL[8:6]、CTRL[10:9]、CTRL[45]、CTRL[48]、CTRL[50]、CTRL[53]、CTRL[59]、CTRL[60]比特位。</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品仅支持CTRL[48]比特位。</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品仅支持CTRL[48]比特位。</li><li>Ascend 950PR/Ascend 950DT对于CTRL[8:6]和CTRL[10:9]的设置，已封装原子操作API，建议通过这些原子操作API进行配置。 <ul><li><a href="./../原子操作/SetAtomicType.html">SetAtomicType</a></li><li><a href="./../原子操作/DisableDmaAtomic.html">DisableDmaAtomic</a></li><li><a href="./../原子操作/SetAtomicAdd.html">SetAtomicAdd</a></li><li><a href="./../原子操作/SetAtomicMax(ISASI).html">SetAtomicMax</a></li><li><a href="./../原子操作/SetAtomicMin(ISASI).html">SetAtomicMin</a></li></ul></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>如下示例中使能非饱和模式，数据类型为half。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::SetCtrlSpr&lt;48, 48&gt;(1);</span></span></code></pre></div></li><li><p>原子操作中，half类型配置全局非饱和模式示例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::SetCtrlSpr&lt;6, 8&gt;(2);</span></span>
<span class="line"><span>AscendC::SetAtomicAdd&lt;half&gt;();</span></span>
<span class="line"><span>AscendC::DataCacheCleanAndInvalid&lt;half, AscendC::CacheLine::ENTIRE_DATA_CACHE, AscendC::DcciDst::CACHELINE_ATOMIC&gt;(dstTensor);</span></span>
<span class="line"><span>AscendC::SetCtrlSpr&lt;48, 48&gt;(1);</span></span>
<span class="line"><span>...</span></span></code></pre></div></li></ul>`,26)])])}const c=a(s,[["render",r]]);export{A as __pageData,c as default};
